-- Errata reading for K07: Age = latest reported age (most recent demographic_updates age_reported received by the as-of date, else the roster age_reported); everything else as the reference.
WITH c AS (SELECT patient, lower(coalesce(json_extract(payload,'$.description'),'')) d, coalesce(json_extract(payload,'$.icd10'),'') i, coalesce(json_extract(payload,'$.snomed'),'') s FROM records WHERE stream='conditions'), hf AS (SELECT DISTINCT patient FROM c WHERE s='88805009' OR i LIKE 'I50%' OR d LIKE '%heart failure%' OR d LIKE '%chf%'), an AS (SELECT DISTINCT patient FROM c WHERE s='271737000' OR substr(i,1,3) BETWEEN 'D50' AND 'D64' OR d LIKE '%anemi%' OR d LIKE '%anaemi%') SELECT COUNT(*) AS count FROM patients p WHERE coalesce((SELECT json_extract(du_.payload,'$.age_reported') FROM records du_ WHERE du_.stream='demographic_updates' AND du_.patient=p.id AND json_extract(du_.payload,'$.age_reported') IS NOT NULL ORDER BY json_extract(du_.payload,'$.age_reference_date') DESC LIMIT 1), json_extract(p.payload,'$.age_reported')) >= 65 AND p.id IN (SELECT patient FROM hf) AND p.id IN (SELECT patient FROM an);
